const metrics = JSON.parse($input.item.json.stdout);
const data_op_ref = metrics.data_op_ref;

// data_op_ref hariç tüm parametreleri al
const excludeKeys = ['data_op_ref'];
const result = [];

for (const [key, value] of Object.entries(metrics)) {
  if (!excludeKeys.includes(key)) {
    result.push({
      data_op_ref: data_op_ref,
      parameter: key,
      value: value
    });
  }
}

return result.map(item => ({ json: item }));

return items.map(item => {
  const [dateRun, deviceId, order, id] = item.json["Run ID"].split("_");
  item.json.DATE_RUN = dateRun;
  item.json.DEVICE_ID = deviceId;
  item.json.ORDER = order;
  item.json.ID = id;
  return item;
});

const dateRunRaw = items[0].json.DATE_RUN;
const dateRun = dateRunRaw.length === 6 ? "20" + dateRunRaw : dateRunRaw;
const deviceId = items[0].json.DEVICE_ID;
const order = items[0].json.ORDER;
const sampleId = items[0].json.Sample_ID;
const cmd = `awk -F',' -v date="${dateRun}" -v device="${deviceId}" -v order="${order}" -v sample="${sampleId}" 'NR>1 && $6==date && $7==device && $8==order && $1==sample {print $0}' /pool0/kozapeta/Data_Consolidation/consolidated/index/20260211_SAMPLEINDEX.csv`;
return [{ json: { command: cmd } }];

const header = "SAMPLE ID,TYPE ID,TYPE,DATE CREATED,DATE ADMITTED,DATE RUN,DEVICE ID,ORDER,RUN ID,PANEL ID,PANEL,KIT,MASTER KIT,PROJECT ID,INSTITUTION ID,INSTITUTION,LAB ID,LAB,ANALYSIS PLATFORM,DATE ANALYZED,SPECIALIST ID,SPECIALIST,CONDITION ID,CONDITION,AGE,GENDER,RAW SEQUENCE,CLINICAL DATA,SUMMARY,SECONDARY,PATH,ERRONEOUS";

const keys = header.split(",");
const values = items[0].json.stdout.trim().split(",");

const result = {};
keys.forEach((key, i) => {
  result[key.trim()] = values[i] || "";
});

return [{ json: result }];

return [
  {
    Library_Prep_Kit: "Sophia-CES-v3",
    bed_file_path: "CES_v3_hg38_original_normalized_chr.bed"
  },
  {
    Library_Prep_Kit: "SOPHIA-CES-V3",
    bed_file_path: "CES_v3_hg38_original_normalized_chr.bed"
  },
  {
    Library_Prep_Kit: "Twist-Human-Core-Exome-WES",
    bed_file_path: "Twist_Exome_hg38_original_normalized_chr.bed"
  },
  {
    Library_Prep_Kit: "Sophia-Solution-Hereditary-Cancer-59-genes",
    bed_file_path: "CHCS_C_v2_target_hg38_liftover_normalized_chr.bed"
  },
  {
    Library_Prep_Kit: "Sophia-HCS-v2",
    bed_file_path: "HCS_v2_0_1_hg38_target_normalized.bed"
  },
  {
    Library_Prep_Kit: "Twist-Human-Core-Exome-WES-mtDNA",
    bed_file_path: "Twist_Exome_hg38_original_with_mtDNA_normalized_chr.bed"
  },
  {
    Library_Prep_Kit: "Twist-Human-Core-Exome-WES+mtDNA",
    bed_file_path: "Twist_Exome_hg38_original_with_mtDNA_normalized_chr.bed"
  }
];

return items.map(item => {
  const input = item.json;
  const lines = (input.stdout || '').trim().split('\n').filter(l => l.startsWith('{'));

  if (lines.length === 0) {
    return { json: { ...input, peta_results: [], peta_found: false } };
  }

  const peta_results = lines.map(l => JSON.parse(l));

  return {
    json: {
      ...input,
      peta_found: true,
      peta_results
    }
  };
});
